using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Xunit;

namespace MyApp.Evaluation;

public class EvaluationTests(DistributedApplicationFixture fixture) : IClassFixture<DistributedApplicationFixture>
{
    [Theory]
    [InlineData("Hello, how can you help me?")]
    [InlineData("What is the capital of France?")]
    [InlineData("If I have 3 apples and give away 1, how many do I have left? Explain your reasoning.")]
    public async Task ChatRespondsWithRelevantContent(string prompt)
    {
        var chatClient = fixture.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, prompt)
        };

        var response = await chatClient.GetResponseAsync(messages);

        Assert.NotNull(response);
        Assert.NotEmpty(response.Text);

        // Evaluate response quality using the AI evaluation metrics.
        var evaluators = new IEvaluator[]
        {
            new RelevanceTruthAndCompletenessEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
        };

        var evaluationResult = await EvaluateAsync(chatClient, messages, response, evaluators);

        foreach (var (name, metric) in evaluationResult)
        {
            if (metric is NumericMetric numeric)
            {
                Assert.True(
                    numeric.Value >= 3.0,
                    $"Metric '{name}' scored {numeric.Value}, expected >= 3.0");
            }
        }
    }

    private static async Task<EvaluationResult> EvaluateAsync(
        IChatClient chatClient,
        IList<ChatMessage> messages,
        ChatResponse response,
        IEnumerable<IEvaluator> evaluators)
    {
        var result = new EvaluationResult();

        foreach (var evaluator in evaluators)
        {
            var evalResult = await evaluator.EvaluateAsync(
                messages,
                response,
                chatClient);

            foreach (var kvp in evalResult)
            {
                result.Add(kvp.Key, kvp.Value);
            }
        }

        return result;
    }
}

using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

namespace MyApp.Evaluation;

/// <summary>
/// Hosts the Aspire distributed application for integration testing and evaluation.
/// Provides access to the configured <see cref="IChatClient"/> resource.
/// </summary>
public class DistributedApplicationFixture : IAsyncLifetime
{
    private DistributedApplication? _app;

    public IChatClient ChatClient { get; private set; } = null!;

    public async ValueTask InitializeAsync()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        _app = await builder.BuildAsync();
        var resourceNotificationService = _app.Services.GetRequiredService<ResourceNotificationService>();

        await _app.StartAsync();

        // Wait for the chat resource to be running.
        await resourceNotificationService.WaitForResourceHealthyAsync("chat");

        ChatClient = _app.Services.GetRequiredService<IChatClient>();
    }

    public async ValueTask DisposeAsync()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }
}

